import { Atom } from "@effect-atom/atom-react"
import { Effect } from "effect"

interface StorageBin {
  readonly code: string
  readonly aisle: string
  readonly available: boolean
}

const bins: ReadonlyArray<StorageBin> = [
  { code: "A-101", aisle: "Receiving", available: true },
  { code: "B-204", aisle: "Cold storage", available: false },
  { code: "C-310", aisle: "Dispatch", available: true }
]

export const searchAvailableBins = Atom.fn<string>()(
  Effect.fn("warehouse.searchAvailableBins")(function* (term) {
    const query = term.trim().toLowerCase()

    yield* Effect.logDebug("Searching available storage bins", { query })

    return bins.filter((bin) => {
      if (!bin.available) return false
      if (query.length === 0) return true

      return (
        bin.code.toLowerCase().includes(query) ||
        bin.aisle.toLowerCase().includes(query)
      )
    })
  })
)
